package ama.storage;
import java.net.*;import java.net.http.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import com.sun.net.httpserver.*;
/** Test-owned exact destination-only relay. Rejects every other method/path before upstream I/O. */
final class Task11Fix03DestinationRelay implements AutoCloseable {
 final HttpServer server;final ExecutorService executor=Executors.newFixedThreadPool(2);final AtomicInteger destinations=new AtomicInteger(),blocked=new AtomicInteger(),failures=new AtomicInteger();final int upstream;
 Task11Fix03DestinationRelay(int upstream)throws Exception{this.upstream=upstream;server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),2);server.setExecutor(executor);server.createContext("/",exchange->{try(exchange){if(!exchange.getRequestMethod().equals("POST")||!exchange.getRequestURI().toString().equals("/v1/knowledge/destination-authorizations")){blocked.incrementAndGet();exchange.sendResponseHeaders(409,0);return;}byte[] body=exchange.getRequestBody().readNBytes(65537);if(body.length>65536)throw new IllegalArgumentException("Relay body bound");var request=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+upstream+exchange.getRequestURI())).timeout(Duration.ofSeconds(5)).header("Content-Type","application/json").header("Authorization",exchange.getRequestHeaders().getFirst("Authorization")).header("X-Controlled-Delegation",exchange.getRequestHeaders().getFirst("X-Controlled-Delegation")).POST(HttpRequest.BodyPublishers.ofByteArray(body)).build();var response=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).followRedirects(HttpClient.Redirect.NEVER).build().send(request,HttpResponse.BodyHandlers.ofInputStream());byte[] result;try(var stream=response.body()){result=stream.readNBytes(65537);}if(result.length>65536)throw new IllegalArgumentException("Relay response bound");destinations.incrementAndGet();exchange.getResponseHeaders().set("Content-Type","application/json");exchange.sendResponseHeaders(response.statusCode(),result.length);exchange.getResponseBody().write(result);}catch(Exception failure){failures.incrementAndGet();}});server.start();}
 int port(){return server.getAddress().getPort();}Map<String,Integer> traffic(){return Map.of("destinationPosts",destinations.get(),"blockedOtherRequests",blocked.get(),"failures",failures.get());}
 public void close()throws Exception{server.stop(0);executor.shutdownNow();if(!executor.awaitTermination(5,TimeUnit.SECONDS))throw new IllegalStateException("Relay cleanup bounded");}
}
